// scenario.ts — the trial's fixed seed, reimplemented.
//
// The conformance suite builds every name it uses from one constant seed (a xorshift64* stream
// seeded by FNV-1a over a label). The login the bearer token owns is users[0].login of that
// scenario, so the entry derives the same login from the same seed rather than being told it.
// Nothing here reads a clock or a random source.

/** 2^64 - 1: the PRNG state mask. */
const U64_MASK = 0xffffffffffffffffn;
/** The one seed every generated byte derives from. */
const SCENARIO_SEED = 0x6a09e667f3bcc909n;
/** How many users the scenario builds. */
const SCENARIO_USERS = 12;

const FIRST_NAMES = [
  'ada', 'bram', 'cora', 'dmitri', 'elena', 'felix', 'greta', 'hugo', 'iris', 'jonas', 'kira', 'lars',
  'mira', 'nico', 'olga', 'pavel', 'quinn', 'rosa', 'sven', 'tess', 'ulla', 'vito', 'wren', 'yara', 'zane',
];
const LAST_NAMES = [
  'anders', 'bauer', 'costa', 'dahl', 'eriksen', 'fischer', 'garcia', 'holm', 'iversen', 'jansen', 'keller',
  'lind', 'moreau', 'novak', 'olsen', 'peters', 'quist', 'rossi', 'sato', 'turi', 'ulrich', 'vega', 'weber',
  'xu', 'yilmaz', 'zimmer',
];

/** FNV-1a, 64-bit. */
function fnv1a64(text: string): bigint {
  let hash = 0xcbf29ce484222325n;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= BigInt(text.charCodeAt(i));
    hash = (hash * 0x100000001b3n) & U64_MASK;
  }
  return hash;
}

/** splitmix64's finalizer. */
function mix64(value: bigint): bigint {
  let z = (value + 0x9e3779b97f4a7c15n) & U64_MASK;
  z = ((z ^ (z >> 30n)) * 0xbf58476d1ce4e5b9n) & U64_MASK;
  z = ((z ^ (z >> 27n)) * 0x94d049bb133111ebn) & U64_MASK;
  return (z ^ (z >> 31n)) & U64_MASK;
}

/** xorshift64*, one named stream. */
class Rng {
  private state: bigint;

  constructor(seed: bigint) {
    const masked = seed & U64_MASK;
    this.state = masked === 0n ? SCENARIO_SEED : masked;
  }

  static fromLabel(label: string): Rng {
    return new Rng(mix64(SCENARIO_SEED ^ fnv1a64(label)));
  }

  nextU64(): bigint {
    let x = this.state;
    x = (x ^ (x >> 12n)) & U64_MASK;
    x = (x ^ (x << 25n)) & U64_MASK;
    x = (x ^ (x >> 27n)) & U64_MASK;
    this.state = x;
    return (x * 0x2545f4914f6cdd1dn) & U64_MASK;
  }

  nextU32(): number {
    return Number(this.nextU64() >> 32n);
  }

  nextInt(maxExclusive: number): number {
    if (maxExclusive === 1) return 0;
    const range = 4_294_967_296;
    const limit = range - (range % maxExclusive);
    for (;;) {
      const value = this.nextU32();
      if (value < limit) return value % maxExclusive;
    }
  }

  pick<T>(items: readonly T[]): T {
    return items[this.nextInt(items.length)] as T;
  }
}

export interface ScenarioUser {
  readonly id: number;
  readonly login: string;
  readonly name: string;
  readonly email: string;
}

/** `count` unique users, in the scenario's own order. */
export function scenarioUsers(count: number = SCENARIO_USERS): ScenarioUser[] {
  const rng = Rng.fromLabel('users');
  const used = new Set<string>();
  const users: ScenarioUser[] = [];
  for (let i = 0; i < count; i += 1) {
    const first = rng.pick(FIRST_NAMES);
    const last = rng.pick(LAST_NAMES);
    const base = `${first}${last}`.replace(/[^a-z0-9-]/g, '');
    let login = base;
    let suffix = 2;
    while (used.has(login)) {
      login = `${base}-${suffix}`;
      suffix += 1;
    }
    used.add(login);
    users.push({ id: 1000 + i, login, name: `${first} ${last}`, email: `${login}@example.invalid` });
  }
  return users;
}

let cached: ScenarioUser[] | null = null;

/** The scenario's user list, built once. */
export function users(): readonly ScenarioUser[] {
  if (cached === null) cached = scenarioUsers();
  return cached;
}

/** The login the trial's bearer token owns (scenario.viewer). */
export function viewerLogin(): string {
  return users()[0]!.login;
}

/** The second user's login (scenario.teammate). */
export function teammateLogin(): string {
  return users()[1]!.login;
}

/** The third user's login (scenario.stranger): the one with no rights on the viewer's repos. */
export function strangerLogin(): string {
  return users()[2]!.login;
}
